  .welcome-side {
    padding-left: calc(var(--g-spacing-10) * 2);
    padding-right: calc(var(--g-spacing-10) * 2);
  }
}

@media (max-width: 1000px) {
  .login-side {
    padding-left: var(--g-spacing-6);
    padding-right: var(--g-spacing-6);
  }
  .welcome-side {
    padding-left: var(--g-spacing-6);
    padding-right: var(--g-spacing-6);
  }
  .welcome-footer-label {
    max-width: 190px;
  }
}

@media (max-width: 760px) {
  .login-page {
    display: flex;
    padding: 0;
  }
  .login-side {
    flex: 1;
    padding: var(--g-spacing-8) var(--g-spacing-6) var(--g-spacing-6);
